  'سيصبح العقد «ملغي» وتتحول الوحدة إلى شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'معاہدہ "منسوخ" ہو جائے گا اور یونٹ خالی ہو جائے گا۔ جاری رکھیں؟\n\nنوٹ: منسوخی کے بعد یہ معاہدہ اور اس کے واجبات رپورٹس سے غائب ہو جاتے ہیں۔ اگر مستقبل میں یونٹ یا اس کی معلومات درکار ہوں تو منسوخی کے بجائے آرکائیو کرنا بہتر ہے۔',
  'أُلغي العقد وأصبحت الوحدة شاغرة': 'معاہدہ منسوخ ہو گیا اور یونٹ اب خالی ہے',
