  'الوحدة شاغرة ولا يوجد عقد لإلغائه': 'یونٹ خالی ہے؛ منسوخ کرنے کے لیے کوئی معاہدہ نہیں',
  'سيُلغى عقد الإيجار بعد عمل التسوية، ويصبح العقد «ملغي» والوحدة شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'تصفیہ کے بعد کرایہ نامہ منسوخ ہوگا؛ معاہدہ "منسوخ" اور یونٹ خالی ہو جائے گا۔ جاری رکھیں؟\n\nنوٹ: منسوخی کے بعد یہ معاہدہ اور اس کے واجبات رپورٹس سے غائب ہو جاتے ہیں۔ اگر مستقبل میں یونٹ یا اس کی معلومات درکار ہوں تو منسوخی کے بجائے آرکائیو کرنا بہتر ہے۔',
