  'الاتصال سليم، لكن هذا الحساب لا يملك أي سجل. هذا يعني غالبًا أن البيانات محفوظة تحت حساب آخر (حساب مجهول قديم) — شغّل ملف _recover_old_data.sql في Supabase لنقل الملكية إلى المعرّف الظاهر أعلاه.': 'کنکشن ٹھیک ہے، لیکن اس اکاؤنٹ کے کوئی ریکارڈ نہیں۔ عام طور پر اس کا مطلب ہے کہ ڈیٹا کسی دوسرے اکاؤنٹ (پرانے گمنام اکاؤنٹ) کے تحت محفوظ ہے — ملکیت اوپر دکھائے گئے شناختی نمبر پر منتقل کرنے کے لیے Supabase میں _recover_old_data.sql فائل چلائیں۔',
