  'لا توجد أعمال صيانة مسجّلة لهذه الوحدة بعد. أضف صيانة وحدّد من يتحمّلها: المؤجر أم المستأجر.': 'اس یونٹ کے لیے ابھی کوئی دیکھ بھال درج نہیں۔ دیکھ بھال شامل کریں اور بتائیں کہ خرچ کون اٹھائے گا: مالک یا کرایہ دار۔',
