  'لا توجد تقارير منشأة بعد.\nابدأ من زر "إنشاء تقرير جديد" في الأعلى.': 'ابھی کوئی رپورٹ نہیں بنی۔\nاوپر "نئی رپورٹ بنائیں" بٹن سے شروع کریں۔',
  'لا توجد حركات مسجّلة بعد.\nاستخدم أزرار الدخل والمصروف والتحويل أعلاه.': 'ابھی کوئی لین دین درج نہیں۔\nاوپر آمدنی، خرچ اور منتقلی کے بٹن استعمال کریں۔',
  'لا توجد حركة مالية مسجّلة لهذه الوحدة بعد. استخدم زر "الدخل / الإيراد" لتسجيل دخل، أو زر "المصروف" لتسجيل مصروف عليها.': 'اس یونٹ کے لیے ابھی کوئی مالی لین دین درج نہیں۔ آمدنی درج کرنے کے لیے "آمدنی" بٹن، یا خرچ درج کرنے کے لیے "خرچ" بٹن استعمال کریں۔',
  'لا توجد سجلات للربط بها بعد': 'ابھی منسلک کرنے کے لیے کوئی ریکارڈ نہیں',
  'لا توجد عمليات مالية بعد': 'ابھی کوئی مالی کارروائی نہیں',
  'لا توجد عناصر تحتاج إلى متابعة حالياً': 'فی الحال کسی آئٹم کو پیروی کی ضرورت نہیں',
  'لا توجد عناصر مؤرشفة بعد.\nأنشئ أرشيفًا جديدًا أو أرشف تقريرًا من صفحة التقارير.': 'ابھی کوئی آرکائیو شدہ آئٹم نہیں۔\nنیا آرکائیو بنائیں یا رپورٹس کے صفحے سے رپورٹ آرکائیو کریں۔',
  'لا توجد عناصر متابعة أو مهام بعد': 'ابھی کوئی پیروی کا آئٹم یا کام نہیں',
  'لا توجد عناصر محفوظة': 'کوئی محفوظ آئٹم نہیں',
  'لا توجد عناصر مطابقة لهذا الاختيار.': 'اس انتخاب سے کوئی آئٹم مطابقت نہیں رکھتا۔',
  'لا توجد فروع بعد — هذا هو النشاط الرئيسي، ويمكنك إضافة فرع مرتبط به من الزر بالأسفل.': 'ابھی کوئی شاخ نہیں — یہ مرکزی سرگرمی ہے، اور آپ نیچے والے بٹن سے منسلک شاخ شامل کر سکتے ہیں۔',
  'لا توجد متابعات مسجّلة لهذه الوحدة بعد.': 'اس یونٹ کے لیے ابھی کوئی پیروی درج نہیں۔',
  'لا توجد محافظ بعد.\nأضف محفظتك الأولى من زر "+ محفظة".': 'ابھی کوئی والٹ نہیں۔\n"+ والٹ" بٹن سے اپنا پہلا والٹ شامل کریں۔',
  'لا توجد مرافق مسجّلة بعد — تُضاف المرافق العامة من شاشة إضافة الوحدات والمرافق (زر + إضافة في قسم الوحدات).': 'ابھی کوئی سہولت درج نہیں — عوامی سہولیات یونٹس اور سہولیات شامل کرنے کی اسکرین سے شامل ہوتی ہیں (یونٹس حصے میں + شامل کریں بٹن)۔',
  'لا توجد مستندات': 'کوئی دستاویز نہیں',
  'لا توجد مستندات بعد': 'ابھی کوئی دستاویز نہیں',
