  'لا توجد وحدات بعد — استخدم زر + إضافة لإضافة شقة أو محل جديد لهذا العقار.': 'ابھی کوئی یونٹ نہیں — اس جائیداد کے لیے نیا فلیٹ یا دکان شامل کرنے کے لیے + شامل کریں بٹن استعمال کریں۔',
  'لا توجد وحدات من هذا النوع حاليًا.': 'فی الحال اس قسم کے کوئی یونٹس نہیں۔',
  'لا تُشارَك بياناتك مع أي طرف ثالث ولا تُستخدم في الإعلانات. ما تشاركه أنت عبر زر المشاركة يخرج بإرادتك ووسيلتك أنت.': 'آپ کا ڈیٹا کسی تیسرے فریق کے ساتھ شیئر نہیں ہوتا اور اشتہارات کے لیے استعمال نہیں ہوتا۔ شیئر بٹن سے جو آپ شیئر کرتے ہیں وہ آپ کی اپنی مرضی اور ذرائع سے جاتا ہے۔',
  'لا يمكن الإضافة لأن الحساب مجمّد': 'اکاؤنٹ منجمد ہونے کی وجہ سے شامل نہیں کیا جا سکتا',
  'لا يمكن التعديل لأن السجل مجمّد. ألغِ التجميد أولاً.': 'ریکارڈ منجمد ہونے کی وجہ سے ترمیم نہیں ہو سکتی۔ پہلے اسے غیر منجمد کریں۔',
