  'إنه في يوم {تاريخ تحرير العقد} بمدينة {مكان تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول (المؤجر): {اسم المؤجر}، والطرف الثاني (المستأجر): {اسم المستأجر}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'بتاریخ {تاريخ تحرير العقد} بمقام {مكان تحرير العقد} فریقِ اول (مالک): {اسم المؤجر} اور فریقِ دوم (کرایہ دار): {اسم المستأجر} کے درمیان معاہدہ طے پایا۔ دونوں فریق معاہدہ کرنے کی قانونی اہلیت کا اقرار کرتے ہیں اور درج ذیل پر متفق ہیں:',
  'أقرّ أنا الموقّع أدناه {اسم المدين}، حامل الهوية رقم {رقم هوية المدين}، بأنني استلمت من {اسم الدائن}، حامل الهوية رقم {رقم هوية الدائن}، مبلغًا وقدره {المبلغ} ({المبلغ كتابةً}) على سبيل {نوع المبلغ}، وذلك بتاريخ {تاريخ الاستلام}.': 'میں، زیرِ دستخطی {اسم المدين}، شناختی نمبر {رقم هوية المدين}، اقرار کرتا ہوں کہ میں نے {اسم الدائن}، شناختی نمبر {رقم هوية الدائن}، سے {المبلغ} ({المبلغ كتابةً}) کی رقم بطور {نوع المبلغ} بتاریخ {تاريخ الاستلام} وصول کی۔',
  'إنه في يوم {تاريخ تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول: {الطرف الأول}، والطرف الثاني: {الطرف الثاني}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'بتاریخ {تاريخ تحرير العقد} فریقِ اول: {الطرف الأول} اور فریقِ دوم: {الطرف الثاني} کے درمیان معاہدہ طے پایا۔ دونوں فریق معاہدہ کرنے کی قانونی اہلیت کا اقرار کرتے ہیں اور درج ذیل پر متفق ہیں:',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ إليه عند انتهاء العقد بعد خصم قيمة أي أضرار أو مستحقات قائمة.': 'کرایہ دار نے {مبلغ التأمين} زرِ ضمانت ادا کیا ہے، جو معاہدے کے اختتام پر کسی بھی نقصان یا واجب الادا رقم کی کٹوتی کے بعد واپس کیا جائے گا۔',
  'شروط إضافية: {شروط إضافية}': 'اضافی شرائط: {شروط إضافية}',
  'حُرِّر هذا العقد من نسختين، بيد كل طرف نسخة للعمل بموجبها.': 'یہ معاہدہ دو نسخوں میں تحریر کیا گیا ہے، ہر فریق کے پاس عمل درآمد کے لیے ایک نسخہ ہے۔',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، ولا يُجدَّد إلا باتفاق مكتوب بين الطرفين.': 'معاہدے کی مدت {تاريخ بداية العقد} سے {تاريخ نهاية العقد} تک ہے، اور فریقین کے تحریری اتفاق کے بغیر اس کی تجدید نہیں ہوگی۔',
  'الأجرة السنوية {قيمة الإيجار السنوي}، تُدفع {طريقة الدفع} مقدمًا في مواعيد استحقاقها، ولا يحق للمستأجر تأخيرها أو الامتناع عنها.': 'سالانہ کرایہ {قيمة الإيجار السنوي} ہے، جو {طريقة الدفع} مقررہ تاریخوں پر پیشگی ادا کیا جائے گا؛ کرایہ دار اسے مؤخر کرنے یا روکنے کا حق نہیں رکھتا۔',
  'إذا تأخر المستأجر عن سداد الأجرة أو أخلّ بأي من التزاماته، يحق للمؤجر المطالبة بفسخ العقد وبما يستحقه وفق الأنظمة المعمول بها.': 'اگر کرایہ دار کرایے کی ادائیگی میں تاخیر کرے یا اپنی کسی ذمہ داری کی خلاف ورزی کرے تو مالک نافذ قوانین کے مطابق معاہدہ منسوخ کرنے اور واجب الادا رقم کا مطالبہ کر سکتا ہے۔',
  'سبب الدين: {سبب الدين}.': 'قرض کی وجہ: {سبب الدين}۔',
  'أتعهد بردّ المبلغ كاملًا إلى الدائن أو من يفوّضه في موعد أقصاه {تاريخ السداد}، وطريقة السداد: {طريقة السداد}.': 'میں عہد کرتا ہوں کہ پوری رقم قرض خواہ یا اس کے مجاز نمائندے کو زیادہ سے زیادہ {تاريخ السداد} تک واپس کروں گا۔ ادائیگی کا طریقہ: {طريقة السداد}۔',
  'يُسدَّد المبلغ على {عدد الأقساط} أقساط، قيمة كل قسط {قيمة القسط}.': 'رقم {عدد الأقساط} اقساط میں ادا کی جائے گی، ہر قسط {قيمة القسط} کی ہوگی۔',
  'يُعدّ هذا الإيصال سندًا بالمبلغ، ويحق للدائن عند التأخر عن السداد المطالبة به بالطرق النظامية.': 'یہ رسید رقم کا ثبوت ہے، اور ادائیگی میں تاخیر کی صورت میں قرض خواہ قانونی طریقوں سے اس کا مطالبہ کر سکتا ہے۔',
  'وهذا إقرار مني بذلك وأنا بكامل أهليتي المعتبرة شرعًا ونظامًا.': 'میں یہ اقرار مکمل شرعی و قانونی اہلیت کے ساتھ کرتا ہوں۔',
  'يستعمل المستأجر العقار للغرض المتفق عليه ({الغرض من الإيجار}) فقط، ولا يحق له التأجير من الباطن أو التنازل عن العقد إلا بموافقة كتابية من المؤجر.': 'کرایہ دار جائیداد کو صرف طے شدہ مقصد ({الغرض من الإيجار}) کے لیے استعمال کرے گا، اور مالک کی تحریری اجازت کے بغیر ذیلی کرایہ داری یا معاہدے کی منتقلی کا حق نہیں رکھتا۔',
  'فواتير الخدمات (الكهرباء والماء والاتصالات) على {فواتير الخدمات على}، والصيانة البسيطة على {الصيانة البسيطة على}، والصيانة الأساسية والإنشائية على {الصيانة الأساسية على}.': 'یوٹیلیٹی بل (بجلی، پانی اور مواصلات) {فواتير الخدمات على} کے ذمے، معمولی مرمت {الصيانة البسيطة على} کے ذمے، اور بڑی و تعمیراتی مرمت {الصيانة الأساسية على} کے ذمے ہے۔',
  'لا يجوز للمستأجر إجراء أي تعديلات أو إنشاءات في العقار إلا بموافقة كتابية من المؤجر.': 'کرایہ دار مالک کی تحریری اجازت کے بغیر جائیداد میں کوئی تبدیلی یا تعمیر نہیں کر سکتا۔',
  'يلتزم المستأجر بالمحافظة على العقار وتسليمه عند انتهاء العقد بالحالة التي استلمه بها، عدا الاستهلاك المعتاد.': 'کرایہ دار جائیداد کی حفاظت کرے گا اور معاہدے کے اختتام پر اسے اسی حالت میں واپس کرے گا جس میں وصول کی تھی، سوائے معمول کی ٹوٹ پھوٹ کے۔',
  'منح المؤجر المستأجر فترة سماح للتجهيز مدتها {فترة السماح للتجهيز} لا تُحتسب فيها أجرة.': 'مالک کرایہ دار کو تیاری کے لیے {فترة السماح للتجهيز} کی رعایتی مدت دیتا ہے جس میں کوئی کرایہ نہیں لیا جائے گا۔',
  'يستعمل المستأجر المحل لممارسة نشاط ({نوع النشاط}) تحت الاسم التجاري ({الاسم التجاري}) فقط، ولا يحق له تغيير النشاط أو التأجير من الباطن إلا بموافقة كتابية من المؤجر.': 'کرایہ دار دکان کو صرف ({نوع النشاط}) کے کاروبار کے لیے تجارتی نام ({الاسم التجاري}) کے تحت استعمال کرے گا، اور مالک کی تحریری اجازت کے بغیر کاروبار تبدیل کرنے یا ذیلی کرایہ داری کا حق نہیں رکھتا۔',
  'يلتزم المستأجر باستخراج التراخيص اللازمة لنشاطه وتجديدها قبل انتهائها، ويتحمّل وحده أي مخالفات أو غرامات تنشأ عن نشاطه.': 'کرایہ دار اپنے کاروبار کے لیے ضروری لائسنس حاصل کرنے اور ان کی میعاد ختم ہونے سے پہلے تجدید کا پابند ہے، اور اپنے کاروبار سے پیدا ہونے والی کسی بھی خلاف ورزی یا جرمانے کا تنہا ذمہ دار ہے۔',
  'فواتير الخدمات على {فواتير الخدمات على}، والصيانة على {الصيانة على}، واللوحات والديكور على {اللوحات والديكور على}.': 'یوٹیلیٹی بل {فواتير الخدمات على} کے ذمے، مرمت {الصيانة على} کے ذمے، اور سائن بورڈ و سجاوٹ {اللوحات والديكور على} کے ذمے ہے۔',
  'عند انتهاء العقد يسلّم المستأجر المحل خاليًا من الشواغل وبالحالة التي استلمه بها، وتؤول التحسينات الثابتة للمؤجر ما لم يُتفق على غير ذلك.': 'معاہدے کے اختتام پر کرایہ دار دکان کو خالی اور اسی حالت میں واپس کرے گا جس میں وصول کی تھی، اور مستقل بہتریاں مالک کی ملکیت ہوں گی جب تک کہ کچھ اور طے نہ ہو۔',
  'مدة الإيجار من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، وأجرة المركبة {قيمة الإيجار} على أساس {أساس التأجير}.': 'کرایے کی مدت {تاريخ بداية العقد} سے {تاريخ نهاية العقد} تک ہے، اور گاڑی کا کرایہ {قيمة الإيجار} بحساب {أساس التأجير} ہے۔',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ عند إعادة المركبة سليمة بعد خصم أي مستحقات.': 'کرایہ دار نے {مبلغ التأمين} زرِ ضمانت ادا کیا ہے، جو گاڑی صحیح سلامت واپس کرنے پر کسی بھی واجب الادا رقم کی کٹوتی کے بعد واپس کیا جائے گا۔',
  'استلم المستأجر المركبة بحالة جيدة، وقراءة العداد {قراءة العداد عند التسليم} كم، ومستوى الوقود {مستوى الوقود عند التسليم}، ويعيدها بالحالة نفسها.': 'کرایہ دار نے گاڑی اچھی حالت میں وصول کی، میٹر ریڈنگ {قراءة العداد عند التسليم} کلومیٹر اور ایندھن کی سطح {مستوى الوقود عند التسليم} تھی، اور وہ اسے اسی حالت میں واپس کرے گا۔',
  'الكيلومترات المسموحة {الكيلومترات المسموحة} كم، وما زاد عليها يُحتسب بواقع {رسوم الكيلومتر الإضافي} لكل كيلومتر.': 'اجازت شدہ فاصلہ {الكيلومترات المسموحة} کلومیٹر ہے؛ اس سے زائد پر فی کلومیٹر {رسوم الكيلومتر الإضافي} وصول کیا جائے گا۔',
  'المستأجر مسؤول عن المخالفات المرورية والحوادث وما يترتب عليها طوال مدة الإيجار، وعليه إبلاغ المؤجر والجهات المختصة فور وقوع أي حادث.': 'کرایے کی پوری مدت کے دوران ٹریفک خلاف ورزیوں، حادثات اور ان کے نتائج کا ذمہ دار کرایہ دار ہے، اور کسی بھی حادثے کی صورت میں فوراً مالک اور متعلقہ حکام کو اطلاع دینا لازم ہے۔',
  'لا يحق للمستأجر السماح لغيره بقيادة المركبة، أو استعمالها في غير الغرض المعتاد، أو الخروج بها خارج الدولة إلا بموافقة كتابية من المؤجر.': 'کرایہ دار مالک کی تحریری اجازت کے بغیر نہ کسی اور کو گاڑی چلانے دے سکتا ہے، نہ اسے غیر معمولی مقصد کے لیے استعمال کر سکتا ہے، اور نہ ملک سے باہر لے جا سکتا ہے۔',
  'الوقود على {الوقود على}، والصيانة الدورية على {الصيانة الدورية على}، ونوع التأمين على المركبة: {التأمين على المركبة}.': 'ایندھن {الوقود على} کے ذمے، معمول کی دیکھ بھال {الصيانة الدورية على} کے ذمے، اور گاڑی کے بیمے کی قسم: {التأمين على المركبة}۔',
  'التأخر في إعادة المركبة عن الموعد المحدد يُحتسب بأجرة يوم كامل عن كل يوم تأخير أو جزء منه.': 'گاڑی مقررہ وقت پر واپس نہ کرنے کی صورت میں تاخیر کے ہر دن یا اس کے کسی حصے کا پورے دن کا کرایہ وصول کیا جائے گا۔',
