  'إنذار رسمي بمهلة وإجراء مطلوب': 'مہلت اور مطلوبہ اقدام کے ساتھ باضابطہ انتباہ',
  'نماذج جاهزة باسمك': 'آپ کے نام کے تیار فارم',
  'أضف شعارك من «التوقيع الإلكتروني والختم» ليظهر أعلى كل نموذج': 'اپنا لوگو «الیکٹرانک دستخط اور مہر» سے شامل کریں تاکہ ہر فارم کے اوپر دکھے',
  'يُطبع كل نموذج بشعارك، ومعه توقيعك وختمك إن اخترت': 'ہر فارم آپ کے لوگو کے ساتھ، اور چاہیں تو دستخط و مہر کے ساتھ پرنٹ ہوتا ہے',
  'الإيصالات والفواتير': 'رسیدیں اور انوائسز',
  'العقود والإنذارات': 'معاہدے اور انتباہات',
  'الإدخال في هذا القسم محدود في باقتك الحالية — للإدخال بلا حد رقِّ باقتك.': 'آپ کے موجودہ پیکج میں اس سیکشن میں اندراج محدود ہے — لامحدود اندراج کے لیے اپ گریڈ کریں۔',
  'وصلت إلى حد الإدخال في باقتك الحالية — للمزيد رقِّ باقتك.': 'آپ اپنے موجودہ پیکج کی اندراج حد تک پہنچ گئے — مزید کے لیے اپ گریڈ کریں۔',
  'إدخال بلا حد': 'لامحدود اندراج',
  'إدخال محدود': 'محدود اندراج',
  'آخر تحديث: 12 أكتوبر 2026': 'آخری تازہ کاری: 12 اکتوبر 2026',
  'توضح هذه السياسة كيف يجمع تطبيق Fundly بياناتك ويستخدمها ويحميها، وحقوقك عليها. باستخدامك التطبيق فأنت توافق على ما ورد فيها.': 'یہ پالیسی وضاحت کرتی ہے کہ Fundly ایپ آپ کا ڈیٹا کیسے جمع کرتی، استعمال کرتی اور محفوظ رکھتی ہے، اور اس پر آپ کے کیا حقوق ہیں۔ ایپ استعمال کر کے آپ اس میں درج شرائط سے اتفاق کرتے ہیں۔',
  'من نحن ونطاق السياسة': 'ہمارا تعارف اور پالیسی کا دائرۂ کار',
  'تطبيق Fundly («التطبيق»، «نحن») لإدارة الأموال والالتزامات والأصول والعلاقات. تسري هذه السياسة على كل ما يُجمع أو يُعالَج عبر التطبيق وخدماته، وتُطبَّق وفق نظام حماية البيانات الشخصية في المملكة العربية السعودية ولائحته التنفيذية، وأنظمة حماية البيانات المعمول بها في بلد المستخدم بالقدر الذي ينطبق عليه.': 'Fundly («ایپ»، «ہم») مالیات، ذمہ داریوں، اثاثوں اور تعلقات کے انتظام کی ایک ایپ ہے۔ یہ پالیسی ایپ اور اس کی خدمات کے ذریعے جمع یا پراسیس کیے جانے والے تمام ڈیٹا پر لاگو ہوتی ہے، اور اس کا اطلاق مملکتِ سعودی عرب کے ذاتی ڈیٹا کے تحفظ کے قانون (PDPL) اور اس کے نفاذی ضوابط، نیز صارف کے ملک میں نافذ ڈیٹا کے تحفظ کے قوانین کے مطابق، جس حد تک وہ اس پر لاگو ہوں، کیا جاتا ہے۔',
  'البيانات التي نجمعها': 'وہ ڈیٹا جو ہم جمع کرتے ہیں',
  '• بيانات الحساب: الاسم، ورقم الهاتف أو البريد الإلكتروني المستخدم في الدخول، والرقم التعريفي الذي يُنشئه التطبيق لك.\n• البيانات التي تدخلها بنفسك: الالتزامات والمصروفات والدخل والديون والعهد والأقساط، وبيانات العقارات والأنشطة والمركبات وعقود الإيجار والدفعات، والمستندات والمرفقات والنماذج والتقارير.\n• بيانات أشخاص آخرين تسجّلها أنت: مثل المستأجرين والمؤجرين والأفراد والجهات وأرقام هوياتهم وهواتفهم.\n• الموقع الجغرافي: عند ضغطك زر جلب الموقع فقط، وبعد إذنك.\n• بيانات تقنية محدودة يلزمها التشغيل، مثل سجلات الاتصال لدى مزوّد الاستضافة لأغراض الأمان.\nلا نستخدم أدوات إعلانات أو تتبّع أو تحليلات سلوكية من أطراف ثالثة.': '• اکاؤنٹ کا ڈیٹا: نام، لاگ اِن کے لیے استعمال ہونے والا فون نمبر یا ای میل، اور وہ شناختی نمبر جو ایپ آپ کے لیے بناتی ہے۔\n• وہ ڈیٹا جو آپ خود درج کرتے ہیں: ذمہ داریاں، اخراجات، آمدنی، قرضے، امانتیں اور اقساط؛ جائیدادوں، کاروباری سرگرمیوں، گاڑیوں، کرایہ داری کے معاہدوں اور ادائیگیوں کا ڈیٹا؛ نیز دستاویزات، منسلکات، فارم اور رپورٹیں۔\n• دوسرے افراد کا ڈیٹا جو آپ درج کرتے ہیں: جیسے کرایہ دار، مالکانِ جائیداد، افراد اور ادارے، اور ان کے شناختی و فون نمبر۔\n• جغرافیائی مقام: صرف اس وقت جب آپ مقام حاصل کرنے کا بٹن دبائیں، اور آپ کی اجازت کے بعد۔\n• آپریشن کے لیے درکار محدود تکنیکی ڈیٹا، جیسے سیکیورٹی کے مقاصد کے لیے ہوسٹنگ فراہم کنندہ کے پاس موجود کنکشن لاگز۔\nہم فریقِ ثالث کے اشتہاری، ٹریکنگ یا رویّہ جاتی تجزیاتی ٹولز استعمال نہیں کرتے۔',
  'لماذا نعالج بياناتك': 'ہم آپ کا ڈیٹا کیوں پراسیس کرتے ہیں',
  '• تقديم خدمات التطبيق وحفظ سجلاتك ومزامنتها بين أجهزتك.\n• إنشاء التذكيرات والتنبيهات والتقارير التي تطلبها.\n• تنفيذ المشاركة التي تختارها مع مستخدمين آخرين (العهد والديون والالتزامات المشتركة والتفويضات).\n• الرد على طلبات الدعم.\n• حماية الحسابات ومنع الاستخدام غير المشروع والالتزام بالأنظمة.\nنعالج البيانات لتنفيذ الخدمة التي طلبتها، وبموافقتك فيما يحتاج موافقة (الموقع والكاميرا والصور)، وللوفاء بالتزاماتنا النظامية. ولا نستخدمها لأي غرض آخر دون إبلاغك.': '• ایپ کی خدمات فراہم کرنا، آپ کے ریکارڈ محفوظ رکھنا اور انہیں آپ کے آلات کے درمیان ہم آہنگ (سنک) کرنا۔\n• آپ کی طلب کردہ یاد دہانیاں، انتباہات اور رپورٹیں تیار کرنا۔\n• دوسرے صارفین کے ساتھ آپ کی منتخب کردہ شراکت کو نافذ کرنا (امانتیں، قرضے، مشترکہ ذمہ داریاں اور اختیارات کی تفویض)۔\n• معاونت کی درخواستوں کا جواب دینا۔\n• اکاؤنٹس کا تحفظ، غیر قانونی استعمال کی روک تھام اور قوانین کی پابندی۔\nہم ڈیٹا کو آپ کی طلب کردہ خدمت کی انجام دہی کے لیے، جہاں رضامندی درکار ہو وہاں آپ کی رضامندی سے (مقام، کیمرہ اور تصاویر)، اور اپنی قانونی ذمہ داریوں کی تکمیل کے لیے پراسیس کرتے ہیں۔ ہم آپ کو مطلع کیے بغیر اسے کسی اور مقصد کے لیے استعمال نہیں کرتے۔',
  'أين تُحفظ بياناتك': 'آپ کا ڈیٹا کہاں محفوظ کیا جاتا ہے',
  '• السجلات الأساسية والمرفقات المرفوعة تُحفظ لدى مزوّد الاستضافة السحابية (Supabase)، مقيّدة بحسابك بضوابط وصول على مستوى السجل، فلا يطّلع عليها حساب آخر إلا ما تشاركه أنت.\n• تُحفظ على جهازك فقط: التفضيلات، وصورة الملف الشخصي، ورمز قفل التطبيق، والتوقيع والختم والشعار، ودليل الأفراد والجهات، والمستندات العامة، والتذكيرات المحلية. حذف التطبيق يحذف هذه البيانات من الجهاز.\n• قد تُعالَج البيانات على خوادم خارج بلدك، ونلتزم عندئذ بالضمانات التي تشترطها الأنظمة لنقل البيانات خارج الحدود.': '• بنیادی ریکارڈ اور اپ لوڈ کیے گئے منسلکات کلاؤڈ ہوسٹنگ فراہم کنندہ (Supabase) کے پاس محفوظ کیے جاتے ہیں، اور ریکارڈ کی سطح پر رسائی کے کنٹرولز کے ذریعے آپ کے اکاؤنٹ تک محدود ہوتے ہیں، لہٰذا کوئی دوسرا اکاؤنٹ انہیں نہیں دیکھ سکتا سوائے اس کے جو آپ خود شیئر کریں۔\n• صرف آپ کے آلے پر محفوظ کیا جاتا ہے: ترجیحات، پروفائل تصویر، ایپ لاک کوڈ، دستخط، مہر اور لوگو، افراد اور اداروں کی ڈائریکٹری، عمومی دستاویزات، اور مقامی یاد دہانیاں۔ ایپ حذف کرنے سے یہ ڈیٹا آلے سے حذف ہو جاتا ہے۔\n• ڈیٹا آپ کے ملک سے باہر سرورز پر پراسیس کیا جا سکتا ہے، اور ایسی صورت میں ہم سرحد پار ڈیٹا کی منتقلی کے لیے قوانین کی مقرر کردہ ضمانتوں کی پابندی کرتے ہیں۔',
  'مشاركة البيانات والإفصاح عنها': 'ڈیٹا کی شراکت اور افشا',
  '• لا نبيع بياناتك ولا نؤجّرها ولا نشاركها لأغراض تسويقية.\n• المشاركة داخل التطبيق تتم بطلبك: عند إسناد عهدة أو دين أو إضافة عضو بالرقم التعريفي يرى الطرف الآخر العنصر المشترك واسمك فقط، ولا يُكشف هاتفك أو عنوانك إلا بموافقتك.\n• ما تشاركه عبر زر المشاركة أو الطباعة (PDF أو صورة) يخرج بإرادتك وعبر التطبيق الذي تختاره.\n• نستعين بمزوّدي خدمة (الاستضافة والتخزين) يعالجون البيانات نيابةً عنّا وفق التزامات تعاقدية بالسرية والأمان.\n• قد نفصح عن البيانات إذا ألزمنا بذلك نظام أو أمر قضائي أو جهة مختصة.': '• ہم آپ کا ڈیٹا نہ فروخت کرتے ہیں، نہ کرائے پر دیتے ہیں اور نہ ہی مارکیٹنگ کے مقاصد کے لیے شیئر کرتے ہیں۔\n• ایپ کے اندر شراکت آپ کی درخواست پر ہوتی ہے: جب آپ کوئی امانت یا قرض تفویض کرتے ہیں یا شناختی نمبر کے ذریعے کسی رکن کو شامل کرتے ہیں تو دوسرا فریق صرف مشترکہ آئٹم اور آپ کا نام دیکھتا ہے، اور آپ کا فون نمبر یا پتہ آپ کی رضامندی کے بغیر ظاہر نہیں کیا جاتا۔\n• جو کچھ آپ شیئر یا پرنٹ کے بٹن کے ذریعے (PDF یا تصویر کی صورت میں) شیئر کرتے ہیں وہ آپ کی مرضی سے اور آپ کی منتخب کردہ ایپ کے ذریعے باہر جاتا ہے۔\n• ہم خدمات فراہم کنندگان (ہوسٹنگ اور اسٹوریج) کی مدد لیتے ہیں جو رازداری اور سلامتی کی معاہداتی ذمہ داریوں کے تحت ہماری جانب سے ڈیٹا پراسیس کرتے ہیں۔\n• اگر کوئی قانون، عدالتی حکم یا مجاز ادارہ ہمیں پابند کرے تو ہم ڈیٹا ظاہر کر سکتے ہیں۔',
  '• الكاميرا والصور والملفات: لإرفاق المستندات والصور والختم والشعار وصورة الملف الشخصي.\n• الموقع: لتعبئة حقل الموقع عند طلبك فقط.\n• الإنترنت: لمزامنة بياناتك.\nيمكنك سحب أي إذن من إعدادات جهازك في أي وقت، وتبقى بقية خصائص التطبيق تعمل.': '• کیمرہ، تصاویر اور فائلیں: دستاویزات، تصاویر، مہر، لوگو اور پروفائل تصویر منسلک کرنے کے لیے۔\n• مقام: صرف آپ کی درخواست پر مقام کا خانہ پُر کرنے کے لیے۔\n• انٹرنیٹ: آپ کا ڈیٹا ہم آہنگ (سنک) کرنے کے لیے۔\nآپ کسی بھی وقت اپنے آلے کی ترتیبات سے کوئی بھی اجازت واپس لے سکتے ہیں، اور ایپ کی باقی خصوصیات کام کرتی رہیں گی۔',
  'الاحتفاظ بالبيانات': 'ڈیٹا کو محفوظ رکھنے کی مدت',
  'نحتفظ ببياناتك ما دام حسابك قائمًا. ما تحذفه ينتقل إلى سلة المهملات حتى تحذفه نهائيًا. وعند حذف الحساب تُحذف بياناته من أنظمتنا خلال مدة لا تتجاوز 30 يومًا، عدا ما يلزم الاحتفاظ به نظامًا، وتُزال من النسخ الاحتياطية وفق دورتها.': 'ہم آپ کا ڈیٹا اس وقت تک محفوظ رکھتے ہیں جب تک آپ کا اکاؤنٹ موجود ہے۔ جو کچھ آپ حذف کرتے ہیں وہ ردی کی ٹوکری میں منتقل ہو جاتا ہے یہاں تک کہ آپ اسے مستقل طور پر حذف کر دیں۔ اکاؤنٹ حذف ہونے پر اس کا ڈیٹا زیادہ سے زیادہ 30 دن کے اندر ہمارے نظاموں سے حذف کر دیا جاتا ہے، سوائے اس ڈیٹا کے جسے قانوناً محفوظ رکھنا لازم ہو، اور بیک اپ نسخوں سے ان کے مقررہ دور کے مطابق ہٹا دیا جاتا ہے۔',
  'أمن البيانات': 'ڈیٹا کی سلامتی',
  '• تشفير الاتصال بين التطبيق والخوادم (TLS).\n• ضوابط وصول تقصر كل سجل على صاحبه ومن يشاركه.\n• قفل التطبيق برمز، وخيار إخفاء المبالغ.\nلا توجد وسيلة نقل أو تخزين آمنة تمامًا، لذا نوصيك بحماية جهازك وعدم مشاركة رمز القفل.': '• ایپ اور سرورز کے درمیان کنکشن کی خفیہ کاری (TLS)۔\n• رسائی کے کنٹرولز جو ہر ریکارڈ کو اس کے مالک اور ان افراد تک محدود رکھتے ہیں جن کے ساتھ وہ اسے شیئر کرے۔\n• کوڈ کے ذریعے ایپ لاک، اور رقوم چھپانے کا اختیار۔\nترسیل یا ذخیرہ کرنے کا کوئی بھی طریقہ مکمل طور پر محفوظ نہیں، اس لیے ہم آپ کو مشورہ دیتے ہیں کہ اپنے آلے کی حفاظت کریں اور لاک کوڈ کسی کے ساتھ شیئر نہ کریں۔',
  'حقوقك': 'آپ کے حقوق',
  'وفق الأنظمة المعمول بها لك الحق في:\n• العلم بكيفية جمع بياناتك ومعالجتها.\n• الوصول إلى بياناتك والحصول على نسخة منها.\n• تصحيحها أو تحديثها.\n• طلب حذفها أو إتلافها.\n• الرجوع عن موافقتك فيما بُني عليها.\n• تقديم شكوى إلى الجهة المختصة بحماية البيانات في بلدك (في المملكة العربية السعودية: الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»).\nنرد على طلبك خلال 30 يومًا من استلامه.': 'نافذ قوانین کے مطابق آپ کو یہ حق حاصل ہے کہ:\n• آپ کو معلوم ہو کہ آپ کا ڈیٹا کیسے جمع اور پراسیس کیا جاتا ہے۔\n• اپنے ڈیٹا تک رسائی حاصل کریں اور اس کی نقل حاصل کریں۔\n• اسے درست یا اپ ڈیٹ کروائیں۔\n• اسے حذف یا تلف کرنے کی درخواست کریں۔\n• جو پراسیسنگ آپ کی رضامندی پر مبنی ہو اس کے لیے اپنی رضامندی واپس لیں۔\n• اپنے ملک میں ڈیٹا کے تحفظ کے مجاز ادارے کے پاس شکایت درج کرائیں (مملکتِ سعودی عرب میں: سعودی ڈیٹا اینڈ آرٹیفیشل انٹیلیجنس اتھارٹی (SDAIA))۔\nہم آپ کی درخواست موصول ہونے کے 30 دن کے اندر اس کا جواب دیتے ہیں۔',
  'حذف الحساب': 'اکاؤنٹ کا حذف',
  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم زر «طلب حذف الحساب» أسفل هذه الصفحة، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': 'آپ کسی بھی وقت کوئی بھی ریکارڈ اس کی اسکرین کے اندر سے حذف کر سکتے ہیں۔ اپنا اکاؤنٹ اور اس کا تمام ڈیٹا حذف کرنے کے لیے اس صفحے کے نیچے «اکاؤنٹ حذف کرنے کی درخواست» کا بٹن استعمال کریں، یا اپنے اکاؤنٹ سے منسلک ای میل یا نمبر سے ہمیں سپورٹ ای میل پر لکھیں؛ ہم درخواست کی تصدیق کر کے اس پر عمل درآمد کریں گے۔',
  'بيانات الآخرين التي تدخلها': 'دوسروں کا ڈیٹا جو آپ درج کرتے ہیں',
  'عند تسجيلك بيانات أشخاص آخرين (كالمستأجرين أو الأفراد أو أطراف العقود) فأنت مسؤول عن أن يكون لديك أساس نظامي لذلك، وأن تستخدمها لأغراضك المشروعة فقط.': 'جب آپ دوسرے افراد (جیسے کرایہ دار، افراد یا معاہدوں کے فریقین) کا ڈیٹا درج کرتے ہیں تو آپ اس بات کے ذمہ دار ہیں کہ آپ کے پاس اس کی قانونی بنیاد موجود ہو، اور آپ اسے صرف اپنے جائز مقاصد کے لیے استعمال کریں۔',
  'الاشتراكات والمدفوعات': 'سبسکرپشنز اور ادائیگیاں',
  'عند تفعيل الاشتراكات المدفوعة تتم عمليات الدفع عبر متاجر التطبيقات أو بوابات دفع مرخّصة، ولا نحفظ بيانات بطاقتك.': 'ادائیگی والی سبسکرپشنز فعال ہونے پر ادائیگیاں ایپ اسٹورز یا لائسنس یافتہ ادائیگی گیٹ ویز کے ذریعے کی جاتی ہیں، اور ہم آپ کے کارڈ کی تفصیلات محفوظ نہیں کرتے۔',
  'الأطفال': 'بچے',
  'التطبيق موجّه لمن بلغ 18 عامًا، ولا نجمع عن قصد بيانات من هم دون ذلك.': 'ایپ 18 سال یا اس سے زائد عمر کے افراد کے لیے ہے، اور ہم جان بوجھ کر اس سے کم عمر افراد کا ڈیٹا جمع نہیں کرتے۔',
  'التعديلات على السياسة': 'پالیسی میں ترامیم',
  'قد نحدّث هذه السياسة، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'ہم اس پالیسی کو اپ ڈیٹ کر سکتے ہیں، اور کسی بھی بنیادی تبدیلی کے نافذ ہونے سے پہلے آپ کو ایپ کے اندر مطلع کریں گے۔ نفاذ کے بعد ایپ کا استعمال جاری رکھنے کا مطلب تازہ ترین نسخے سے آپ کا اتفاق ہے۔',
  'التواصل معنا': 'ہم سے رابطہ کریں',
  'لأي سؤال أو طلب يتعلق بخصوصيتك راسلنا على بريد الدعم: support@fundly.app': 'اپنی رازداری سے متعلق کسی بھی سوال یا درخواست کے لیے ہمیں سپورٹ ای میل پر لکھیں: support@fundly.app',
  'طلب حذف الحساب': 'اکاؤنٹ حذف کرنے کی درخواست',
  'سيُفتح بريدك برسالة جاهزة لطلب حذف حسابك وكل بياناته نهائيًا. أرسلها من البريد أو الرقم المرتبط بحسابك. هل تريد المتابعة؟': 'آپ کی ای میل ایپ ایک تیار شدہ پیغام کے ساتھ کھلے گی جس میں آپ کے اکاؤنٹ اور اس کے تمام ڈیٹا کو مستقل طور پر حذف کرنے کی درخواست ہوگی۔ اسے اپنے اکاؤنٹ سے منسلک ای میل یا نمبر سے بھیجیں۔ کیا آپ جاری رکھنا چاہتے ہیں؟',
  'تعذّر فتح البريد — نُسخ بريد الدعم لتراسلنا منه': 'ای میل نہیں کھل سکی — سپورٹ ای میل کاپی کر لی گئی ہے تاکہ آپ ہم سے رابطہ کر سکیں',
