  'كل مصروف يرسله المستلم يصلك لتعتمده أو ترفضه، ولا يُخصم من العهدة قبل اعتماده.': 'وصول کنندہ کا ہر خرچ آپ کے پاس منظوری یا مسترد کرنے کے لیے آتا ہے، اور منظوری سے پہلے عہدہ سے نہیں کٹتا۔',
