  'العهدة مسندة — الصرف عند الطرف الآخر، وكل مصروف يرسله يصلك هنا لتعتمده أو ترفضه.': 'عہدہ سونپ دیا گیا ہے — خرچ دوسرا فریق کرتا ہے، اور اس کا بھیجا ہر خرچ یہاں منظوری یا مسترد کرنے کے لیے آتا ہے۔',
