  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم «حذف الحساب» في الإعدادات تحت «تسجيل الخروج»، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': 'آپ کسی بھی ریکارڈ کو کسی بھی وقت اس کی اسکرین سے حذف کر سکتے ہیں۔ اپنا اکاؤنٹ اور اس کا تمام ڈیٹا حذف کرنے کے لیے ترتیبات میں «لاگ آؤٹ» کے نیچے «اکاؤنٹ حذف کریں» استعمال کریں، یا اپنے اکاؤنٹ سے منسلک ای میل یا نمبر سے سپورٹ کو لکھیں، ہم تصدیق کر کے درخواست پوری کریں گے۔',
