  'بياناتك محفوظة في حسابك وتظهر في أي جوال تدخل منه بنفس الحساب. تتم المزامنة تلقائيًا كل 30 ثانية وعند فتح التطبيق والخروج منه. افتح هذه الصفحة في الجوالين: يجب أن يكون الحساب والأرقام نفسها.': 'آپ کا ڈیٹا آپ کے اکاؤنٹ میں محفوظ ہے اور اسی اکاؤنٹ سے کسی بھی فون پر نظر آتا ہے۔ ہم آہنگی ہر 30 سیکنڈ اور ایپ کھولنے اور بند کرنے پر خود ہوتی ہے۔ یہ صفحہ دونوں فونز پر کھولیں: اکاؤنٹ اور نمبر ایک جیسے ہونے چاہئیں۔',
