  '، ثم يعود حسابك إلى الباقة الأساسية وتبقى بياناتك محفوظة. لا تُسترد المبالغ المدفوعة عن المدة الحالية.': '، پھر آپ کا اکاؤنٹ بنیادی پلان پر واپس آ جائے گا اور آپ کا ڈیٹا محفوظ رہے گا۔ موجودہ مدت کی ادا شدہ رقم واپس نہیں ہوگی۔',
