  'اكتب «تاريخ الميلاد» في تعديل الملف الشخصي — والباقي يحسبه التطبيق لك.': 'پروفائل میں ترمیم میں تاریخ پیدائش لکھیں — باقی حساب ایپ کر لے گی۔',
  'الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، ولا يضيف التطبيق أي رسوم أخرى. قد يطبّق البنك أو المتجر رسوم تحويل العملة.': 'دکھائی گئی قیمتیں حتمی ہیں اور جہاں لاگو ہو ویلیو ایڈڈ ٹیکس شامل ہے؛ ایپ کوئی اضافی فیس نہیں لیتی۔ بینک یا اسٹور کرنسی تبدیلی کی فیس لے سکتا ہے۔',
  'الأهلية والحساب': 'اہلیت اور اکاؤنٹ',
  'الاستخدام المقبول': 'قابل قبول استعمال',
  'الاسترداد': 'رقم کی واپسی',
  'الاشتراك الشهري أو السنوي يتجدد تلقائيًا في نهاية كل مدة بنفس السعر حتى تلغي التجديد. الهدية لا تتجدد وتنتهي بنهاية مدتها.': 'ماہانہ یا سالانہ سبسکرپشن ہر مدت کے اختتام پر اسی قیمت پر خود بخود تجدید ہوتی ہے جب تک آپ تجدید منسوخ نہ کریں۔ تحفہ تجدید نہیں ہوتا اور اپنی مدت پر ختم ہو جاتا ہے۔',
  'الاشتراك المُهدى يبدأ يوم تفعيل كوده من المُهدى إليه، وينتهي بنهاية مدته دون تجديد. لا تُسترد قيمة الهدية بعد شرائها أو تفعيلها، ولا تُستبدل نقدًا.': 'تحفے کی سبسکرپشن اس دن شروع ہوتی ہے جب وصول کنندہ کوڈ فعال کرے، اور مدت ختم ہونے پر بغیر تجدید ختم ہو جاتی ہے۔ خریداری یا فعال ہونے کے بعد تحفے کی رقم واپس نہیں ہوتی اور نقد میں تبدیل نہیں ہوتی۔',
  'التجديد التلقائي': 'خودکار تجدید',
  'التطبيق أداة لتنظيم وتسجيل الأموال والالتزامات والأصول والعلاقات. ما يعرضه من أرقام وتنبيهات وتقارير مبني على ما تدخله أنت، ولا يُعد استشارة مالية أو قانونية أو محاسبية أو ضريبية.': 'ایپ رقم، ذمہ داریوں، اثاثوں اور تعلقات کو منظم اور درج کرنے کا ایک آلہ ہے۔ اس کے اعداد، انتباہات اور رپورٹس آپ کے درج کردہ ڈیٹا پر مبنی ہیں اور مالی، قانونی، حسابی یا ٹیکس مشورہ نہیں ہیں۔',
  'التعديلات على الشروط': 'شرائط میں تبدیلیاں',
  'التواصل بشأن المدفوعات': 'ادائیگیوں کے بارے میں رابطہ',
  'التوفر والتعديلات على الخدمة': 'سروس کی دستیابی اور تبدیلیاں',
  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. يبدأ الاشتراك فورًا ويتجدد تلقائيًا في نهاية المدة حتى تلغي التجديد، وتتغير صلاحيات الأقسام فورًا.': 'ایپ میں ادائیگی ابھی فعال نہیں، اس لیے پلان ابھی آزمائشی طور پر بغیر کسی کٹوتی کے فعال ہوگا۔ سبسکرپشن فوراً شروع ہوگی اور مدت کے اختتام پر خود بخود تجدید ہوگی جب تک آپ منسوخ نہ کریں، اور حصوں کی اجازتیں فوراً بدل جائیں گی۔',
