  'بياناتك ومحتواك': 'آپ کا ڈیٹا اور مواد',
  'تاريخ الميلاد غير صحيح — اكتبه يوم/شهر/سنة مثل 17/9/1984': 'تاریخ پیدائش درست نہیں — دن/مہینہ/سال لکھیں، مثلاً 17/9/1984',
  'تخضع هذه الشروط لأنظمة المملكة العربية السعودية، وتختص محاكمها بالنظر في أي نزاع ينشأ عنها، دون إخلال بحقوقك النظامية في بلد إقامتك.': 'یہ شرائط سعودی عرب کے قوانین کے تابع ہیں اور کسی بھی تنازع پر وہاں کی عدالتیں مجاز ہیں، آپ کے ملکِ رہائش کے قانونی حقوق متاثر کیے بغیر۔',
  'تنبيه: عند إلغاء الاشتراك أو الهدية لا تُسترد المبالغ المدفوعة، ويبقى الاشتراك فعّالًا حتى نهاية مدته.': 'نوٹ: سبسکرپشن یا تحفہ منسوخ کرنے پر ادا شدہ رقم واپس نہیں ہوتی، اور سبسکرپشن اپنی مدت کے اختتام تک فعال رہتی ہے۔',
  'تنظّم هذه الشروط استخدامك تطبيق Fundly وخدماته. باستخدامك التطبيق فأنت توافق عليها وعلى سياسة الخصوصية، فإن لم توافق فتوقف عن الاستخدام.': 'یہ شرائط Fundly ایپ اور اس کی خدمات کے استعمال کو منظم کرتی ہیں۔ ایپ استعمال کر کے آپ ان سے اور رازداری کی پالیسی سے اتفاق کرتے ہیں؛ اگر اتفاق نہیں تو استعمال بند کر دیں۔',
  'تواصل بشأن المدفوعات': 'ادائیگیوں کے بارے میں رابطہ کریں',
  'تُقدَّم الخدمة «كما هي». وبالقدر الذي تسمح به الأنظمة لا نتحمل المسؤولية عن أي خسارة غير مباشرة، أو عن قرارات اتخذتها بناءً على بيانات أدخلتها، أو عن فقد بيانات محفوظة على جهازك فقط.': 'سروس "جیسی ہے" فراہم کی جاتی ہے۔ قانون کی اجازت کی حد تک ہم کسی بالواسطہ نقصان، آپ کے درج کردہ ڈیٹا پر مبنی فیصلوں، یا صرف آپ کے آلے پر محفوظ ڈیٹا کے ضائع ہونے کے ذمہ دار نہیں۔',
  'حدود المسؤولية': 'ذمہ داری کی حدود',
  'سيتجدد اشتراكك تلقائيًا في': 'آپ کی سبسکرپشن خود بخود تجدید ہوگی بتاریخ',
  'شروط الاستخدام': 'شرائط استعمال',
  'شروط الاشتراك والدفع': 'سبسکرپشن اور ادائیگی کی شرائط',
  'شروط الخدمة والاشتراكات والمدفوعات': 'سروس، سبسکرپشن اور ادائیگی کی شرائط',
  'طبيعة الخدمة': 'سروس کی نوعیت',
  'عند إسناد عهدة أو ربط دين أو إضافة أعضاء إلى التزام مشترك، يرى الطرف الآخر العنصر المشترك وما يسجّله فيه. كل طرف مسؤول عمّا يسجّله أو يعتمده، والتطبيق وسيلة توثيق ولا يضمن وفاء أي طرف بالتزاماته تجاه الآخر.': 'جب آپ امانت سونپتے، قرض منسلک کرتے یا مشترکہ ذمہ داری میں اراکین شامل کرتے ہیں تو دوسرا فریق مشترکہ آئٹم اور اس میں درج چیزیں دیکھتا ہے۔ ہر فریق اپنے درج یا منظور کردہ کا ذمہ دار ہے؛ ایپ دستاویز کا ذریعہ ہے اور کسی فریق کی ذمہ داری پوری ہونے کی ضمانت نہیں دیتی۔',
  'قد نحدّث هذه الشروط، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'ہم ان شرائط کو اپ ڈیٹ کر سکتے ہیں اور کسی بھی اہم تبدیلی کے نافذ ہونے سے پہلے ایپ میں آپ کو مطلع کریں گے۔ اس کے بعد استعمال جاری رکھنا نئی شرائط سے اتفاق ہے۔',
  'لأي استفسار عن الدفع أو الفواتير أو الاسترداد راسلنا من «تواصل معنا» على بريد الدعم، مع تاريخ العملية ورقم الإصدار.': 'ادائیگی، انوائس یا رقم کی واپسی کے بارے میں کسی بھی سوال کے لیے "ہم سے رابطہ" سے سپورٹ ای میل پر لکھیں، لین دین کی تاریخ اور ورژن کے ساتھ۔',
  'لأي سؤال عن هذه الشروط أو عن الاشتراكات والمدفوعات راسلنا على بريد الدعم: support@fundly.app': 'ان شرائط یا سبسکرپشن اور ادائیگیوں کے بارے میں کسی بھی سوال کے لیے سپورٹ کو لکھیں: support@fundly.app',
  'لا تُسترد المبالغ المدفوعة عن مدة بدأت، ولا قيمة الهدية بعد شرائها أو تفعيلها، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.': 'شروع ہو چکی مدت کی ادا شدہ رقم اور خریدے یا فعال کیے گئے تحفے کی رقم واپس نہیں ہوتی، سوائے اس کے جو قانون یا ادائیگی والے اسٹور کی پالیسی لازم کرے۔',
  'لا يُقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة، ثم يعود حسابك إلى الباقة الأساسية وتبقى كل بياناتك محفوظة.': 'سبسکرپشن فوراً ختم نہیں ہوتی: ادا شدہ مدت کے اختتام تک فعال رہتی ہے، پھر آپ کا اکاؤنٹ بنیادی پلان پر واپس آ جاتا ہے اور تمام ڈیٹا محفوظ رہتا ہے۔',
  'متى يبدأ الاشتراك': 'سبسکرپشن کب شروع ہوتی ہے',
  'مفعّل': 'فعال',
  'ملغى — يبقى فعّالًا حتى نهاية المدة': 'منسوخ — مدت کے اختتام تک فعال',
  'من هذه الصفحة بزر «إلغاء التجديد التلقائي»، أو من إدارة الاشتراكات في متجر التطبيقات الذي دفعت منه، قبل موعد التجديد بيوم على الأقل.': 'اسی صفحے سے "خودکار تجدید منسوخ کریں" کے ذریعے، یا جس ایپ اسٹور سے ادائیگی کی اس کی سبسکرپشن مینجمنٹ سے، تجدید سے کم از کم ایک دن پہلے۔',
  'نعمل على أن تكون الخدمة متاحة باستمرار، لكن قد تتوقف مؤقتًا للصيانة أو لأسباب خارجة عن إرادتنا. وقد نطوّر الميزات أو نعدّلها، ونُبلغك داخل التطبيق بأي تغيير جوهري يمس اشتراكك.': 'ہم سروس کو ہمیشہ دستیاب رکھنے کی کوشش کرتے ہیں، لیکن دیکھ بھال یا ہمارے اختیار سے باہر وجوہات سے عارضی طور پر رک سکتی ہے۔ ہم خصوصیات بہتر یا تبدیل کر سکتے ہیں اور آپ کی سبسکرپشن پر اثر انداز ہونے والی اہم تبدیلی سے ایپ میں مطلع کریں گے۔',
  'هدية — لا تتجدد': 'تحفہ — تجدید نہیں ہوتی',
  'يبدأ فور تأكيد الدفع وتُحسب مدته من يوم الدفع. والهدية تبدأ يوم تفعيل كودها من المُهدى إليه، لا يوم شرائها.': 'یہ ادائیگی کی تصدیق ہوتے ہی شروع ہوتی ہے اور مدت ادائیگی کے دن سے شمار ہوتی ہے۔ تحفہ اس دن شروع ہوتا ہے جب وصول کنندہ کوڈ فعال کرے، خریداری کے دن نہیں۔',
  'يبقى اشتراكك فعّالًا حتى': 'آپ کی سبسکرپشن فعال رہے گی تا',
  'يتجدد تلقائيًا في': 'خودکار تجدید بتاریخ',
  'يتجدد في': 'تجدید بتاریخ',
  'يمكنك حذف حسابك في أي وقت من الإعدادات. ويحق لنا تعليق الحساب أو إيقافه عند مخالفة هذه الشروط، مع إبلاغك بالسبب ما لم يمنع ذلك نظام.': 'آپ کسی بھی وقت ترتیبات سے اپنا اکاؤنٹ حذف کر سکتے ہیں۔ ان شرائط کی خلاف ورزی پر ہم اکاؤنٹ معطل یا بند کر سکتے ہیں اور وجہ بتائیں گے جب تک قانون منع نہ کرے۔',
  'يوم/شهر/سنة — مثل 17/9/1984': 'دن/مہینہ/سال — مثلاً 17/9/1984',
  'يُمنع استخدام التطبيق في أي نشاط مخالف للأنظمة أو في الاحتيال أو انتحال الشخصية، أو محاولة الوصول إلى حسابات أو بيانات غيرك، أو تعطيل الخدمة، أو نسخ التطبيق أو تفكيكه أو إعادة بيعه.': 'ایپ کو کسی غیر قانونی سرگرمی، دھوکہ دہی یا نقالی، دوسروں کے اکاؤنٹس یا ڈیٹا تک رسائی کی کوشش، سروس میں خلل، یا ایپ کی نقل، ریورس انجینئرنگ یا دوبارہ فروخت کے لیے استعمال کرنا ممنوع ہے۔',
  '• التطبيق لمن بلغ 18 عامًا.\n• أنت مسؤول عن صحة بيانات حسابك، وعن سرية كلمة المرور ورمز قفل التطبيق، وعن كل ما يتم من حسابك.\n• أبلغنا فورًا إن اشتبهت في استخدام حسابك دون إذنك.': '• ایپ 18 سال یا اس سے زائد عمر کے افراد کے لیے ہے۔\n• آپ اپنے اکاؤنٹ کے ڈیٹا کی درستگی، پاس ورڈ اور ایپ لاک کوڈ کی رازداری، اور اپنے اکاؤنٹ سے ہونے والی ہر کارروائی کے ذمہ دار ہیں۔\n• اگر اکاؤنٹ کے بلا اجازت استعمال کا شبہ ہو تو فوراً ہمیں بتائیں۔',
  '• ما تدخله من بيانات ومستندات يبقى ملكك، وتمنحنا حق معالجته بالقدر اللازم لتقديم الخدمة فقط وفق سياسة الخصوصية.\n• أنت مسؤول عن مشروعية ما تسجّله من بيانات أشخاص آخرين وعن حصولك على ما يلزم لذلك.': '• آپ کا درج کردہ ڈیٹا اور دستاویزات آپ کی ملکیت رہتی ہیں؛ آپ ہمیں صرف سروس فراہم کرنے کی حد تک رازداری کی پالیسی کے مطابق ان پر کارروائی کا حق دیتے ہیں۔\n• دوسروں کے درج کردہ ڈیٹا کی قانونی حیثیت اور اس کے لیے ضروری اجازت حاصل کرنا آپ کی ذمہ داری ہے۔',
  '• يبدأ الاشتراك فور تأكيد الدفع وتُحسب مدته من يوم الدفع.\n• يتجدد الاشتراك الشهري أو السنوي تلقائيًا بنفس السعر حتى تلغي التجديد من صفحة الاشتراكات أو من متجر التطبيقات قبل موعد التجديد بيوم على الأقل.\n• إلغاء التجديد لا يقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة ثم يعود الحساب إلى الباقة الأساسية وتبقى البيانات محفوظة.\n• لا تُسترد المبالغ المدفوعة عن مدة بدأت، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.\n• الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، وقد يطبّق البنك أو المتجر رسوم تحويل العملة.': '• سبسکرپشن ادائیگی کی تصدیق ہوتے ہی شروع ہوتی ہے اور مدت ادائیگی کے دن سے شمار ہوتی ہے۔\n• ماہانہ یا سالانہ سبسکرپشن اسی قیمت پر خود بخود تجدید ہوتی ہے جب تک آپ سبسکرپشن صفحے یا ایپ اسٹور سے تجدید سے کم از کم ایک دن پہلے منسوخ نہ کریں۔\n• تجدید منسوخ کرنے سے سبسکرپشن فوراً ختم نہیں ہوتی: ادا شدہ مدت کے اختتام تک فعال رہتی ہے، پھر اکاؤنٹ بنیادی پلان پر واپس آتا ہے اور ڈیٹا محفوظ رہتا ہے۔\n• شروع ہو چکی مدت کی ادا شدہ رقم واپس نہیں ہوتی، سوائے اس کے جو قانون یا ادائیگی والے اسٹور کی پالیسی لازم کرے۔\n• دکھائی گئی قیمتیں حتمی ہیں اور جہاں لاگو ہو ویلیو ایڈڈ ٹیکس شامل ہے؛ بینک یا اسٹور کرنسی تبدیلی کی فیس لے سکتا ہے۔',
  'أضف شعارك من «المزيد» ← «التوقيع الإلكتروني والختم» ليظهر أعلى كل نموذج': 'اپنا لوگو «مزید» ← «الیکٹرانک دستخط اور مہر» سے شامل کریں تاکہ ہر نمونے کے اوپر نظر آئے',
  'أُضيف إلى الأفراد والجهات، ويمكنك من هناك إضافة أي بيانات أخرى عنه': 'افراد اور اداروں میں شامل کر دیا گیا، وہاں سے آپ اس کے بارے میں مزید معلومات شامل کر سکتے ہیں',
  'أُلغيت بعد التسوية في': 'تصفیے کے بعد منسوخ ہوئی بتاریخ',
  'إلغاء العهدة بتسوية': 'تصفیے کے ساتھ امانت منسوخ',
  'ارسم توقيعك هنا بإصبعك': 'یہاں انگلی سے اپنے دستخط بنائیں',
  'اكتب ما تم قبل التسوية': 'تصفیے سے پہلے لکھیں کہ کیا ہوا',
  'بانتظار قبوله': 'اس کی قبولیت کا انتظار',
  'بدون سبب محدد': 'کوئی مخصوص وجہ نہیں',
  'تسوية وإبقاؤها': 'تصفیہ کریں اور رکھیں',
  'تعديل بيانات جهة': 'ادارے کی معلومات میں ترمیم',
  'تعديل بيانات فرد': 'فرد کی معلومات میں ترمیم',
  'تمت التسوية في': 'تصفیہ ہوا بتاریخ',
  'تمت تسوية العهدة — تبقى ظاهرة بحالة «تمت التسوية»': 'امانت کا تصفیہ ہو گیا — «تصفیہ شدہ» حالت میں نظر آتی رہے گی',
  'رفض المستلم العهدة': 'وصول کنندہ نے امانت مسترد کر دی',
  'رفضها': 'مسترد کر دی',
  'ستُغلق العهدة ولا يُصرف منها بعد ذلك. اكتب ما تم في التسوية (مثل: استلمت المتبقي نقدًا)، ثم اختر إبقاءها أو أرشفتها.': 'امانت بند ہو جائے گی اور اس سے مزید خرچ نہیں ہو سکے گا۔ تصفیے میں کیا ہوا لکھیں (مثلاً باقی رقم نقد وصول کی)، پھر رکھنے یا آرکائیو کرنے کا انتخاب کریں۔',
  'قبول المستلم العهدة': 'وصول کنندہ نے امانت قبول کر لی',
  'مفوَّض بإدارة عهدة مالية': 'مالی امانت کے انتظام کا مجاز',
  'ملاحظة التسوية': 'تصفیے کا نوٹ',
  'ملاحظة التسوية — ماذا تم؟ *': 'تصفیے کا نوٹ — کیا ہوا؟ *',
  'لمزيد من التفاصيل اضغط على العهدة، أو افتح «الالتزامات الشخصية» ← «عهدة مالية».': 'مزید تفصیلات کے لیے امانت پر دبائیں، یا «ذاتی ذمہ داریاں» ← «مالی امانت» کھولیں۔',
  'ملغية': 'منسوخ',
  'أضف شعارك من «المزيد» ليظهر أعلى كل نموذج — ومتوفر أيضًا التوقيع والختم': '«مزید» سے اپنا لوگو شامل کریں تاکہ ہر نمونے کے اوپر نظر آئے — دستخط اور مہر بھی دستیاب ہیں',
  'التاريخ والساعة': 'تاریخ اور وقت',
  'تاريخ ووقت التسوية': 'تصفیے کی تاریخ اور وقت',
  'ساعة الصرف': 'خرچ کا وقت',
  'إعادة فتح العهدة': 'امانت دوبارہ کھولیں',
