  'وما فُوِّضتَ به من عقارات ومركبات وأنشطة تجده في قسمه بعلامة «مفوَّض» (دائرة بنفسجية)، وكل ما تقوم به يصل إشعاره لمن فوّضك.': 'آپ کو تفویض کی گئی جائیدادیں، گاڑیاں اور سرگرمیاں اپنے حصے میں «تفویض شدہ» نشان (جامنی دائرہ) کے ساتھ ملیں گی، اور آپ کے ہر عمل کی اطلاع تفویض کرنے والے کو جائے گی۔',
