  'اضغط على السجل لإدارته حسب صلاحياتك، والعقار يُفتح في قسمه — وكل ما تفعله يصل إشعاره للمالك.': 'ریکارڈ پر ٹیپ کر کے اپنی اجازتوں کے مطابق اس کا انتظام کریں؛ جائیداد اپنے حصے میں کھلتی ہے — آپ کے ہر عمل کی اطلاع مالک کو جاتی ہے۔',
  'حفظ التغيير': 'تبدیلی محفوظ کریں',
